class PackageApiRef(BaseApiRef):
    """
    This class inherits from :class:`BaseApiRef`

    :raw-html:`<br />`

    Downloads the API from `pypi`_ at runtime with `pip`_, which also brings the API's own dependencies
    (numpy, FixRaidenBoss2)

    Parameters
    ----------
    package: :class:`str`
        The API, both as a module to import and as an installation name
    """

    def getOptions(self) -> List[CommandOption]:
        return [
            CommandOption((ShortCommandOpts.DisableUpdate.value, CommandOpts.DisableUpdate.value),
                          {"action": "store_true",
                           "help": f"Skips updating '{self.package}' to its latest version before running. With this option, the package is only downloaded when it is not already installed."}),

            CommandOption((ShortCommandOpts.PreRelease.value, CommandOpts.PreRelease.value),
                          {"action": "store_true",
                           "help": f"Also considers prereleases of '{self.package}' when downloading it"})
        ]

    def getInstallCommand(self, args: Any) -> List[str]:
        """
        The `pip`_ command that downloads the API

        Parameters
        ----------
        args: `Namespace`_
            This script's own options, already read

        Returns
        -------
        List[:class:`str`]
            The command, starting with the running python
        """

        result = [sys.executable, "-m", "pip", "install", "-U"]

        if (getattr(args, "preRelease", False)):
            result.append("--pre")

        return result + [self.package]

    def isInstalled(self) -> bool:
        """
        Whether the API can already be imported

        Returns
        -------
        :class:`bool`
            Whether the API is available
        """

        # a search of the import path rather than an import: importing an old version here would leave it
        #   cached in sys.modules, and the script would keep running it after pip has upgraded the package
        return importlib.machinery.PathFinder.find_spec(self.package, self.getImportPath()) is not None

    def canShowFullHelp(self, args: Any) -> bool:
        # printing help never downloads or updates the API, so the full help needs it already installed
        return self.isInstalled()

    def getHelpNote(self) -> str:
        return f"""NOTE:
'{self.package}', the library that makes the identity mods, is not installed on this computer yet,
so only this script's own options are shown above. It is downloaded the first time you run this
script without {CommandOpts.Help.value}.

The full list of options is at:
{DocsCommandOptsUrl}"""

    def prepare(self, args: Any):
        # printing help is not a generating session, so it does not update an installed API either
        skipUpdate = getattr(args, "disableUpdate", False) or getattr(args, "help", False)

        if (skipUpdate and self.isInstalled()):
            return

        command = self.getInstallCommand(args)
        print(f"Getting the latest version of '{self.package}' (pass {CommandOpts.DisableUpdate.value} to skip this)...")
        try:
            subprocess.check_call(command)
        except (OSError, subprocess.CalledProcessError):
            # an installed copy still runs when it only could not be updated (eg. no internet)
            if (self.isInstalled()):
                print(f"Could not update '{self.package}'; running the version already installed")
                return

            # quoted, since a shell reads the '>' of a requirement as a redirection
            commandStr = " ".join(f'"{part}"' for part in command)
            print(f"Could not download '{self.package}'. Install it yourself with: {commandStr}")
            sys.exit(1)

        # a package installed during this run is not on any import path that was cached before it
        #   arrived, so the caches have to be dropped before the import can find it
        importlib.invalidate_caches()


class PathApiRef(BaseApiRef):
    """
    This class inherits from :class:`BaseApiRef`

    :raw-html:`<br />`

    Reaches the API by a path on this machine, the way every tool in this repo reaches the others

    :raw-html:`<br />`

    .. note::
        The API's own dependencies (numpy, FixRaidenBoss2) must already be importable

    Parameters
    ----------
    package: :class:`str`
        The API, both as a module to import and as an installation name

    apiPath: Optional[:class:`str`]
        The folder holding the API's package :raw-html:`<br />` :raw-html:`<br />`

        When this is ``None``, the path is worked out from where this script sits, using the
        relative path the ScriptBuilder compiled in :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``None``
    """

    def __init__(self, package: str, apiPath: Optional[str] = None):
        super().__init__(package)
        self._apiPath = apiPath

    def getApiPath(self) -> str:
        """
        The folder holding the API's package

        Returns
        -------
        :class:`str`
            The folder
        """

        if (self._apiPath is not None):
            return self._apiPath

        scriptFolder = os.path.dirname(os.path.abspath(__file__))
        return os.path.abspath(os.path.join(scriptFolder, *ApiRelPath.split("/")))

    def prepare(self, args: Any):
        apiPath = self.getApiPath()

        if (not os.path.isdir(apiPath)):
            raise FileNotFoundError(f"This is a 'dev' build of the script, which expects the API's source at: {apiPath}")

        # first, so the source wins over any installed release of the API
        sys.path.insert(0, apiPath)


class ApiRefBuilder():
    """
    Picks how this build of the script reaches the API
    """

    @classmethod
    def build(cls) -> BaseApiRef:
        """
        Retrieves the way this build of the script reaches the API

        Returns
        -------
        :class:`BaseApiRef`
            How to reach the API
        """

        if (BuildEnv.match(EnvName) == BuildEnv.Prod):
            return PackageApiRef(ApiPackage)

        return PathApiRef(ApiPackage)


class CommandFormatter(argparse.MetavarTypeHelpFormatter, argparse.RawTextHelpFormatter):
    """
    The layout of this script's help page
    """

    pass


class CommandBuilder():
    """
    Handles the options this script adds on top of the API's own

    Parameters
    ----------
    options: Optional[List[:class:`CommandOption`]]
        The options to add :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``None``
    """

    Description = "Generates the identity mods of characters: the game's own models, written out as mods"
    """
    The description at the top of the help page, the same as the API's
    """

    HelpOpts = (ShortCommandOpts.Help.value, CommandOpts.Help.value)
    """
    The options that ask for the help page
    """

    def __init__(self, options: Optional[List[CommandOption]] = None):
        self.options = [] if (options is None) else options

    def preParse(self, argv: List[str]) -> Tuple[Any, List[str]]:
        """
        Reads only this script's own options, leaving everything else for the API

        :raw-html:`<br />`

        .. note::
            Abbreviations are off. With them on, argparse would happily match a shortened form of an
            *API* option onto one of ours and swallow it.

        Parameters
        ----------
        argv: List[:class:`str`]
            The command line arguments to read

        Returns
        -------
        Tuple[`Namespace`_, List[:class:`str`]]
            The options that were read, with ``help`` set if the help page was asked for, and the arguments
            left over for the API, the help option among them
        """

        parser = argparse.ArgumentParser(add_help = False, allow_abbrev = False)
        for option in self.options:
            option.add(parser.add_argument)

        args, remainingArgs = parser.parse_known_args(argv)

        # the help option is left for the API, which prints the help of whichever game it is given after
        args.help = any(arg in self.HelpOpts for arg in remainingArgs)
        return args, remainingArgs

    def makeParser(self, note: Optional[str] = None, **kwargs) -> argparse.ArgumentParser:
        """
        Makes a parser holding only this script's own options, for printing them

        Parameters
        ----------
        note: Optional[:class:`str`]
            Text to show below the options :raw-html:`<br />` :raw-html:`<br />`

            **Default**: ``None``

        **kwargs
            More arguments for `argparse's ArgumentParser`_

        Returns
        -------
        `argparse's ArgumentParser`_
            The parser
        """

        parser = argparse.ArgumentParser(epilog = note, formatter_class = CommandFormatter, **kwargs)
        for option in self.options:
            option.add(parser.add_argument)
        return parser

    def printHelp(self, note: Optional[str] = None):
        """
        Prints a help page of only this script's own options

        :raw-html:`<br />`

        For when the API, which owns every other option, is not there to print its own

        Parameters
        ----------
        note: Optional[:class:`str`]
            Text to show below the options :raw-html:`<br />` :raw-html:`<br />`

            **Default**: ``None``
        """

        self.makeParser(note = note, description = self.Description).print_help()

    def printOwnOptions(self):
        """
        Prints this script's own options, below the API's help page

        :raw-html:`<br />`

        The API's command has no place to register them into, so they are printed after its help, and can
        be given anywhere on the command line
        """

        if (not self.options):
            return

        parser = self.makeParser(usage = argparse.SUPPRESS, add_help = False,
                                 description = "This script also takes these options, anywhere on the command line:")
        print(f"\n{parser.format_help()}")


def main(argv: Optional[List[str]] = None, apiRef: Optional[BaseApiRef] = None) -> int:
    """
    Runs the script

    :raw-html:`<br />`

    The script does not make the identity mods itself: it makes the API available and then hands the
    command line straight to the API's own ``main``. With no arguments (eg. the script double-clicked), the
    API asks which game and which characters to make the mods of

    Parameters
    ----------
    argv: Optional[List[:class:`str`]]
        The arguments, without the program name. If this value is ``None``, the arguments of the running program are used :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``None``

    apiRef: Optional[:class:`BaseApiRef`]
        How to reach the API :raw-html:`<br />` :raw-html:`<br />`

        When this is ``None``, whichever reference this script was compiled for is used. Running
        this out of the repo rather than from a compiled script is the case that passes one in,
        since the compiled-in values do not exist yet :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``None``

    Returns
    -------
    :class:`int`
        The exit code, as the API's ``main`` returns it
    """

    if (argv is None):
        argv = sys.argv[1:]

    if (apiRef is None):
        apiRef = ApiRefBuilder.build()

    command = CommandBuilder(apiRef.getOptions())

    # this script's own options have to be read before the API is fetched, since one of them decides
    #   whether the API gets downloaded at all. Everything else is the API's
    args, remainingArgs = command.preParse(argv)

    # the API is not fetched just to print its help: when it is not there, the help page only has
    #   this script's own options, and says how to see the rest
    if (args.help and not apiRef.canShowFullHelp(args)):
        command.printHelp(note = apiRef.getHelpNote())
        return 0

    apiMain = apiRef.loadMain(args)
    if (not args.help):
        return apiMain(remainingArgs)

    # the API's help page ends the program, so this script's own options are printed after it
    try:
        apiMain(remainingArgs)
    except SystemExit:
        pass

    command.printOwnOptions()
    return 0


# Main Driver Code
if __name__ == "__main__":
    sys.exit(main())

